        a.bindJalaliPicker(fields.get("birth_date"));a.bindJalaliPicker(fields.get("registration_date"));a.bindLocation(fields.get("province"),fields.get("city"));
        Runnable visibility=()->{boolean legal=type.getSelectedItemPosition()==1;for(String k:new String[]{"first_name","last_name","father_name","birth_date"})fields.get(k).setVisibility(legal?View.GONE:View.VISIBLE);for(String k:new String[]{"legal_type","registration_number","registration_date","representative"})fields.get(k).setVisibility(legal?View.VISIBLE:View.GONE);};
        type.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long row){visibility.run();}});visibility.run();
