        Choice(LinearLayout form,String prompt,List<ContentValues> list,String label){rows=list;ArrayList<String> labels=new ArrayList<>();labels.add(prompt+" — انتخاب نشده");for(ContentValues r:list)labels.add(OfficeV101.text(r,label)+" · "+r.getAsLong("id"));spinner=a.spinner(labels.toArray(new String[0]));form.addView(spinner);}
